  "ev.old30": "यह इनवॉइस 30 या ज़्यादा दिन पुराना है। ₹10 करोड़ या ज़्यादा टर्नओवर पर पोर्टल इसे अब रजिस्टर नहीं करता। नया इनवॉइस बनाने से पहले अपने अकाउंटेंट से पूछें।",
