  "ev.old180": "180 दिन से ज़्यादा पुराने डॉक्यूमेंट का ई-वे बिल पोर्टल नहीं बनाता।",
  "ev.smallst": "{st} के अंदर ई-वे बिल आम तौर पर ₹{v} से ऊपर ही चाहिए (दूसरे राज्य में ₹50,000 से ऊपर; दूसरे राज्य जाने वाले जॉब वर्क और हैंडीक्राफ़्ट पर हर रकम पर चाहिए)।",
  "ev.fromirn": "अगर आपके बिज़नेस को ई-इनवॉइस बनाना होता है, तो इस इनवॉइस का ई-वे बिल पोर्टल सिर्फ़ इसके IRN से बनाता है: “ई-इनवॉइस के साथ ई-वे बिल भी बनाएँ” पर टिक करें और ई-इनवॉइस फ़ाइल बनाएँ।",
