  "app.made": "बना: {x}",
  "app.local": "डेटा होम नहीं खुला, इसलिए सिर्फ़ इसी साइट पर इस ब्राउज़र में सेव है। अगली बार यह डेटा होम में चला जाएगा।",
  "app.vault": "इस ब्राउज़र के डेटा होम में सेव है, जो Nivesh Sahayak के हर टूल में साझा है। हमें कुछ नहीं भेजा जाता।",
  "app.help": "यह कैसे काम करता है",
  "app.helpp": "billing., cash-memo. और credit-note. पर बने बिल यहाँ अपने-आप दिखते हैं। मिला और दिया पैसा यहाँ लिखें; ऐप उसे बिलों से जोड़ता है, एडवांस रखता है और बकाया व हाथ का कैश निकालता है।",
  "app.invfix": "यहाँ चुकते हुए इनवॉइस बिलिंग साइट पर भी पेड दिखेंगे।",
