  "app.ex_ads": "विज्ञापन",
  "app.ex_misc": "अन्य खर्चे",
  "app.back": "‹ वापस",
  "app.advance": "एडवांस",
  "app.advh": "बिल से पहले मिला या दिया पैसा।",
  "app.intro": "आपके बिल, मिला और दिया पैसा, खरीद, खर्चे और बकाया, सब एक जगह। यह फ़्री डॉक्यूमेंट मेकरों (बिलिंग, कोटेशन, रसीद वगैरह) का ही सेव डेटा इस्तेमाल करता है, इसलिए वहाँ बना हर बिल यहाँ दिखता है। फ़्री, बिना लॉगिन, और डेटा इसी ब्राउज़र में रहता है।",
  "app.ab.h": "छोटे बिज़नेस के लिए ऐप क्या करता है",
  "app.ab.p": "ज़्यादातर फ़्री बिल मेकर बिल बनाकर रुक जाते हैं। Nivesh Sahayak App आगे चलता है: हर पेमेंट को उन बिलों से जोड़ता है जिन्हें वह चुकता करता है, ताकि आपको हमेशा पता रहे कि किस कस्टमर पर कितना और कब से बाकी है, और आपको किसे देना है।",
  "app.ab.1": "डैशबोर्ड: आज की और इस महीने की बिक्री, लेना और देना, हाथ में कैश और बैंक में पैसा।",
  "app.ab.2": "पैसा आया और गया: पेमेंट एक बार लिखें और जिन बिलों को वह चुकता करता है उन पर टिक करें। थोड़ा-थोड़ा पेमेंट और एडवांस अपने-आप संभलते हैं, और कस्टमर का काटा TDS भी गिना जाता है।",
  "app.ab.3": "बकाया और पुरानापन: किस पर कितना बाकी, 0–30, 31–60, 61–90 और 90 दिन से ज़्यादा में बँटा हुआ, तैयार WhatsApp रिमाइंडर के साथ।",
  "app.ab.4": "पार्टी स्टेटमेंट: किसी भी तारीख का स्टेटमेंट ऑफ़ अकाउंट, प्रिंट करें या PDF भेजें।",
  "app.ab.5": "खरीद और खर्चे: सप्लायर के बिल, CGST, SGST या IGST अपने-आप; खरीद वापसी; और रोज़ के खर्चे जैसे किराया, बिजली, पेट्रोल।",
  "app.ab.6": "कैश बुक और बैंक बुक: हर कैश और बैंक एंट्री, चलते बैलेंस के साथ।",
  "app.ab.7": "एक क्लिक में बदलें: कोटेशन से सेल्स ऑर्डर, डिलीवरी चालान या इनवॉइस, बिना दोबारा लिखे।",
  "app.ab.end": "अंदर से हर बिल, पेमेंट और खर्चा सही डबल-एंट्री अकाउंट बनता है, जैसा अकाउंटेंट चाहते हैं।",
  "app.ab.link": "पढ़ें ऐप कैसे काम करता है",
