  "g3.w.nogstin": "{p} से खरीद बिल {no} में सप्लायर का GSTIN सही नहीं है, इसलिए उसका ITC GSTR-2B में नहीं दिखेगा।",
  "g3.w.2b": "बॉक्स 4(A)(5) का ITC आपके सेव किए खरीद बिलों और खर्चों से आया है। सिर्फ़ वही क्लेम करें जो आपके GSTR-2B में दिखता है; GSTR-2B का आँकड़ा कम हो तो वही टाइप करें।",
