  "b1.tcsh": "सिर्फ उन बिक्रियों पर जिन पर विक्रेता को इनकम टैक्स वसूलना होता है: इनकम टैक्स एक्ट 2025 का सेक्शन 394 (पहले सेक्शन 206C)। फाइनेंस एक्ट 2026 के बाद के रेट: शराब, तेंदू पत्ता, लकड़ी या वन उपज, स्क्रैप, कोयला, लिग्नाइट या लौह अयस्क 2%; ₹10 लाख से ऊपर की गाड़ी या नोटिफाइड सामान 1%; विदेश टूर पैकेज 2%; पार्किंग, टोल प्लाज़ा, खान या खदान 2%। 1 से 5 वाले सामान पर TCS नहीं अगर खरीदार लिखकर दे कि सामान मैन्युफैक्चरिंग के लिए है, ट्रेडिंग के लिए नहीं। बाकी सामान पर TCS नहीं (₹50 लाख वाला पुराना नियम खत्म)।",
