  "b1.c_tcs10g": "GST के बिना कोई आइटम ₹10 लाख से ऊपर नहीं है, सिर्फ GST जोड़कर ऊपर है। एक्ट में \"वैल्यू\" लिखा है और किसी सर्कुलर ने तय नहीं किया कि इस लिमिट में GST गिना जाए या नहीं। क्या इस बिल पर TCS लेना है?",
